import { decode_Enum, decode_Struct, Enum, encode_Enum, encode_Struct, type Struct } from "./tests.gen.ts";

const SCRATCH = test_scratch_dir("serialize-opaque");
let tmp_n = 0;
/** `tempfile::NamedTempFile::new()` */
const named_temp_file = (): string => join(SCRATCH, `tmp${tmp_n++}`);

// rustc: compiler/rustc_serialize/src/opaque/tests.rs:30 check_round_trip
function check_round_trip<T>(values: T[], encode_T: Encodable<T, FileEncoder>, decode_T: Decodable<T, MemDecoder>): void {
  const tmpfile = named_temp_file();

  const encoder = unwrap_result(FileEncoder.new(tmpfile));
  for (const value of values) {
    encode_T(value, encoder);
  }
  unwrap_result(encoder.finish());
  encoder.drop();

  const data = new Uint8Array(readFileSync(tmpfile));
  const decoder = unwrap_result(MemDecoder.new(data, 0));
  for (const value of values) {
    const decoded = decode_T(decoder);
    expect(decoded).toEqual(value);
  }
}

const U64_MAX = (1n << 64n) - 1n;
const I64_MIN = -(1n << 63n);
const I64_MAX = (1n << 63n) - 1n;

// rustc: compiler/rustc_serialize/src/opaque/tests.rs:53 test_unit
test("test_unit", () => {
  check_round_trip([null, null, null, null], encode_unit, decode_unit);
});

