// rustc: compiler/rustc_serialize/src/opaque/tests.rs:146 test_option
test("test_option", () => {
  const opt = <T>(e: Encodable<T>, d: Decodable<T>): [Encodable<T | undefined>, Decodable<T | undefined>] => [
    (v, s) => encode_Option(v, s, e),
    (dd) => decode_Option(dd, d),
  ];
  check_round_trip([-1], ...opt(encode_i8, decode_i8));
  check_round_trip([-2], ...opt(encode_i16, decode_i16));
  check_round_trip([-3], ...opt(encode_i32, decode_i32));
  check_round_trip([-4n], ...opt(encode_i64, decode_i64));
  check_round_trip([-5], ...opt(encode_isize, decode_isize));

  const none_i8: number | undefined = undefined;
  check_round_trip([none_i8], ...opt(encode_i8, decode_i8));

  const none_i16: number | undefined = undefined;
  check_round_trip([none_i16], ...opt(encode_i16, decode_i16));

  const none_i32: number | undefined = undefined;
  check_round_trip([none_i32], ...opt(encode_i32, decode_i32));

  const none_i64: bigint | undefined = undefined;
  check_round_trip([none_i64], ...opt(encode_i64, decode_i64));

  const none_isize: number | undefined = undefined;
  check_round_trip([none_isize], ...opt(encode_isize, decode_isize));
});

