// rustc: compiler/rustc_serialize/src/opaque/tests.rs:268 test_box
test("test_box", () => {
  // `#[derive(Encodable_NoContext, Decodable_NoContext, PartialEq, Debug)] struct A { foo: Box<[bool]> }`
  interface A {
    foo: boolean[];
  }
  const encode_A = (self: A, e: FileEncoder): void => encode_Box(self.foo, e, (v, s) => encode_slice(v, s, encode_bool));
  const decode_A = (d: MemDecoder): A => ({ foo: decode_Box_slice(d, decode_bool) });

  const obj: A = { foo: [true, false] };
  check_round_trip([obj], encode_A, decode_A);
});

// rustc: compiler/rustc_serialize/src/opaque/tests.rs:279 test_cell
test("test_cell", () => {
  // `#[derive(Encodable_NoContext, Decodable_NoContext, PartialEq, Debug)] struct A { baz: isize }`
  interface A {
    baz: number;
  }
  const encode_A = (self: A, e: FileEncoder): void => encode_isize(self.baz, e);
  const decode_A = (d: MemDecoder): A => ({ baz: decode_isize(d) });

  // `#[derive(Encodable_NoContext, Decodable_NoContext, PartialEq, Debug)] struct B { foo: Cell<bool>, bar: RefCell<A> }`
  interface B {
    foo: boolean;
    bar: A;
  }
  const encode_B = (self: B, e: FileEncoder): void => {
    encode_Cell(self.foo, e, encode_bool);
    encode_RefCell(self.bar, e, (v, s) => encode_A(v, s as FileEncoder));
  };
  const decode_B = (d: MemDecoder): B => ({ foo: decode_Cell(d, decode_bool), bar: decode_RefCell(d, decode_A) });

  const obj: B = { foo: true, bar: { baz: 2 } };
  check_round_trip([obj], encode_B, decode_B);
});

// rustc: compiler/rustc_serialize/src/opaque/tests.rs:298 test_flush_strategy
test("test_flush_strategy", () => {
  const tmpfile = named_temp_file();

  // Small write that is explicitly flushed, and then a chunk larger than BUF_SIZE (64 KiB).
  // to hit `write_all_cold_path`.
  const small = Uint8Array.from({ length: 100 }, (_, i) => i & 0xff);
  const big = Uint8Array.from({ length: 100_000 }, (_, i) => i & 0xff);

  const expected: number[] = [];
  expected.push(...small);
  expected.push(...big);
  expected.push(...MAGIC_END_BYTES);

  const flushed: number[] = [];
  const strategy = (buf: Uint8Array) => {
    flushed.push(...buf);
  };
  const encoder = unwrap_result(FileEncoder.with_flush_strategy(tmpfile, strategy));

  encoder.write_all(small);
  encoder.flush();
  encoder.write_all(big);
  unwrap_result(encoder.finish());

  encoder.drop();

  expect(flushed).toEqual(expected);
  expect(flushed).toEqual([...readFileSync(tmpfile)]);
});
